 $known=@('NATIVE_CHILD_REJECTED','NATIVE_PIPE_BOUND','NATIVE_CHILD_TIMEOUT','OVERLAY_PARAMETER','OVERLAY_RESULT_SHAPE','OVERLAY_RESULT_ROWS','OVERLAY_RESULT_FIELDS','OVERLAY_RESULT_BOUND','OVERLAY_QUANTITATIVE_ROWS','OVERLAY_BEFORE','OVERLAY_CHECKED','OVERLAY_COUNTER_SHAPE','OVERLAY_COUNTER_BOUND','OVERLAY_DBTS_BOUND','OVERLAY_USER_IDENTITY_CHANGED','OVERLAY_DBTS_REGRESSION','OVERLAY_INSERT_COUNTER_LINK','OVERLAY_COMPENSATE_COUNTER_DRIFT','OVERLAY_TRIAL_COUNTER_DRIFT','OVERLAY_DECISION_EXPIRED','OVERLAY_SQL_LIFETIME','OVERLAY_SQL_IDENTITY','OVERLAY_APP_NOT_OFFLINE','OVERLAY_PACKAGE_CHANGED','NATIVE_RESULT_BOUND','NATIVE_REPARSE','OVERLAY_CLOSE');$code='OVERLAY_STEP_FAILED';$meta=@{sqlNumber=$null;sqlLine=$null};$e=$Failure
 for($i=0;$i-lt4-and$null-ne$e;$i++){
  if($e-is[Data.SqlClient.SqlException]){$code='OVERLAY_SQL_FAILED';$meta=Convert-OverlaySqlDiagnostic $e.Number $e.LineNumber;break}
  if($e.Message-cin$known){$code=$e.Message};$e=$e.InnerException
 };return @{stage=$Stage;guard=$code;sqlNumber=$meta.sqlNumber;sqlLine=$meta.sqlLine}
}
